func verifyTestGate(versionDir string, a Attempt) error {
	var report struct {
		SnapshotID         string `json:"snapshot_id"`
		CommandPassed      bool   `json:"command_passed"`
		SnapshotConsistent bool   `json:"snapshot_consistent"`
		ExitCode           int    `json:"exit_code"`
		CommandSHA256      string `json:"command_sha256"`
		OutputSHA256       string `json:"output_sha256"`
	}
	if err := readJSONLoose(filepath.Join(versionDir, "test-gate.json"), &report); err != nil {
		return err
	}
	if report.SnapshotID != a.ResultSnapshotID || !report.CommandPassed || !report.SnapshotConsistent || report.ExitCode != 0 ||
		len(report.CommandSHA256) != 64 || len(report.OutputSHA256) != 64 {
		return fmt.Errorf("candidate test gate did not pass on the patch snapshot")
	}
	return nil
}

// Promote requires an unchanged active base, a passing candidate test gate,
// a current semantic trace and a separate approved human decision plus test
// execution for every criterion. Any rejection holds the candidate.
func Promote(ctx context.Context, dataset, patchID, storePath string) (string, error) {
	a, err := Load(dataset, patchID)
	if err != nil {
		return "", err
	}
	current, err := os.Readlink(filepath.Join(dataset, "current"))
	if err != nil || current != a.BaseVersion {
		return "", fmt.Errorf("patch base is no longer current")
	}
	vdir := filepath.Join(dataset, a.ResultVersion)
	if err := verifyTestGate(vdir, a); err != nil {
		return "", err
	}
	p, err := CandidateProjection(ctx, dataset, a, storePath)
	if err != nil {
		return "", err
	}
	trace, err := p.Trace()
	if err != nil {
		return "", err
	}
	if len(trace.Requirements) == 0 {
		return "", fmt.Errorf("patch candidate has no reviewed requirements")
	}
	for _, r := range trace.Requirements {
		if r.State != semantic.TraceLinked {
			return "", fmt.Errorf("requirement %q is %s, not linked", r.RequirementID, r.State)
		}
	}
	decisions, err := readDecisions(dataset, patchID)
	if err != nil {
		return "", err
	}
	byCriterion := map[string]Decision{}
	for _, d := range decisions {
		if d.PatchID != patchID || d.ProjectID != a.ProjectID || d.DatasetID != a.ResultDatasetID || d.SnapshotID != a.ResultSnapshotID ||
			byCriterion[d.CriterionID].DecisionID != "" || d.Outcome != "approved" || d.ReviewedBy == "" || d.Reason == "" {
			return "", fmt.Errorf("patch has rejected, duplicate, or foreign criterion decision")
		}
		byCriterion[d.CriterionID] = d
	}
	criteria := 0
	for _, r := range p.Requirements {
		for _, c := range r.AcceptanceCriteria {
			criteria++
			d, ok := byCriterion[c.ID]
			if !ok || d.SpecVersion != r.Version {
				return "", fmt.Errorf("criterion %q lacks current human approval", c.ID)
			}
			evidenceSHA := ""
			for _, e := range p.Evidence {
				if e.ID == c.EvidenceID {
					evidenceSHA = e.ContentSHA256
					break
				}
			}
			if evidenceSHA == "" || d.EvidenceSHA256 != evidenceSHA {
				return "", fmt.Errorf("criterion %q approval evidence differs", c.ID)
			}
			run, err := loadRun(dataset, patchID, c.ID)
			if err != nil {
				return "", err
			}
			if err := validateRun(p, c.ID, run); err != nil {
				return "", err
			}
		}
	}
	if len(byCriterion) != criteria {
		return "", fmt.Errorf("patch has decisions for foreign criteria")
	}
	data, err := json.Marshal(decisions)
	if err != nil {
		return "", err
	}
	sum := sha256.Sum256(data)
	return setup.PromoteReviewedCandidateIfBase(dataset, a.ResultVersion, a.BaseVersion, patchID, hex.EncodeToString(sum[:]))
}

// PromoteReviewedCandidate is called only after the patch review workflow has
// checked criterion decisions and the candidate's test report. Ordinary
// promote/rollback refuse a held candidate.
func PromoteReviewedCandidate(dataset, version, patchID, decisionsSHA256 string) (prev string, err error) {
	return promoteReviewedCandidate(dataset, version, "", patchID, decisionsSHA256)
}

// PromoteVersion atomically points <dataset>/current at the built index in
// <dataset>/<version>, after an integrity gate (reindex-migration-design
// §4.1/§5.1). CKS orchestrates *when* to promote and version naming/GC; this is
// the CKV-side atomic-swap primitive it calls.
//
// The version must be a completed build (readable manifest) that passes the
// integrity gate (no orphan chunks/vectors). The swap creates a temporary
// relative symlink and renames it over `current`, so a concurrent reader
// resolving `current` sees either the old or the new target, never a missing
// link.
func PromoteVersion(dataset, version string) error {
	versionDir := filepath.Join(dataset, version)

	m, err := manifest.Load(versionDir)
	if err != nil {
		return fmt.Errorf("promote: version %q has no valid manifest: %w", version, err)
	}

	// Integrity gate: no serving traffic points at an index with orphans.
	store, err := sqlitevec.Open(filepath.Join(versionDir, "vector.db"), m.EmbeddingDim)
	if err != nil {
		return fmt.Errorf("promote: open %q store: %w", version, err)
	}
	val, verr := store.Validate(context.Background())
	_ = store.Close()
	if verr != nil {
		return fmt.Errorf("promote: validate %q: %w", version, verr)
	}
	if !val.OK() {
		return fmt.Errorf("promote: version %q failed integrity gate: %d orphan chunks, %d orphan vectors",
			version, val.OrphanChunks, val.OrphanVectors)
	}

	// Atomic swap: temp relative symlink → rename over `current`.
	current := filepath.Join(dataset, "current")
	tmp := filepath.Join(dataset, fmt.Sprintf(".ckv-current.tmp-%d", os.Getpid()))
	_ = os.Remove(tmp)
	if err := os.Symlink(version, tmp); err != nil {
		return fmt.Errorf("promote: create temp link: %w", err)
	}
	if err := os.Rename(tmp, current); err != nil {
		_ = os.Remove(tmp)
		return fmt.Errorf("promote: swap current: %w", err)
	}
	return nil
}

// Promote atomically points <dataset>/current at <version> (a temp relative
// symlink renamed over `current`, so a concurrent reader resolving `current`
// sees the old or the new target, never a missing one). It returns the version
// `current` pointed at before the swap ("" if none) so the caller can record a
// rollback target. The version directory must already exist.
func Promote(dataset, version string) (prev string, err error) {
	return promote(dataset, version, false)
}

func decodeJSON(path string, out any, strict bool) error {
	info, err := os.Lstat(path)
	if err != nil || !info.Mode().IsRegular() {
		return fmt.Errorf("patch record unavailable: %v", err)
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	dec := json.NewDecoder(bytes.NewReader(data))
	if strict {
		dec.DisallowUnknownFields()
	}
	if err := dec.Decode(out); err != nil {
		return err
	}
	var trailing any
	if err := dec.Decode(&trailing); err != io.EOF {
		return fmt.Errorf("trailing patch JSON")
	}
	return nil
}
